using System;using System.IO;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 [Serializable]public sealed class CompatibilityFixture{public CompatibilityRow[] rows;}
 [Serializable]public sealed class CompatibilityRow{public string action,transfer;public NumberData compute,income,data;public double training,research;}
 public sealed class CompatibilityTests {
  static void Near(ScientificNumber a,NumberData b){var expected=ScientificNumber.FromData(b);if(expected.IsZero)Assert.That(a.IsZero,Is.True);else Assert.That(a.Log10(),Is.EqualTo(expected.Log10()).Within(2e-10));}
  [Test]public void PreservedLegacyFactorsBoostExpiryAndBothResetKindsMatchSource(){var fixture=JsonUtility.FromJson<CompatibilityFixture>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/CompatibilityReferenceCases.json")));GameState s=null;foreach(var row in fixture.rows){var expected=UnityWebImport.Validate(row.transfer);if(row.action=="initial")s=expected;else if(row.action=="advance")s=Game.Advance(s,s.SavedAt+45000);else if(row.action=="prestige")s=PrestigeRules.Reset(s);else if(row.action=="axiom"){s.Prestige.known=Array.ConvertAll(PrestigeBalance.Nodes,n=>n.Id);s=MetaRules.AxiomReset(s);}Near(Game.Compute(s),row.compute);Near(Game.Income(s),row.income);Near(Game.DataRate(s),row.data);Assert.That(Game.WorkSpeed(s),Is.EqualTo(row.training).Within(1e-8));Assert.That(Game.WorkSpeed(s,true),Is.EqualTo(row.research).Within(1e-8));Assert.That(s.Legacy.cycle.Length,Is.EqualTo(expected.Legacy.cycle.Length));Assert.That(PrestigeAutomation.HardwareUnlocked(s,Array.FindIndex(Balance.Hardware,h=>h.Id=="gpu")),Is.True);Assert.That(s.Legacy.prepared,Is.True);var codec=new UnitySaveCodec();s=codec.Decode(codec.Encode(StateData.From(s)),AtomicSaveStore.Version).ToState();}}
  [Test]public void BlueprintReceiptRequiresPaidMainJobAndRespectsCapacity(){foreach(bool challenge in new[]{false,true}){var s=Game.New(1000000);s.Research[Array.FindIndex(Balance.Research,r=>r.Id=="blueprints")]=1;if(challenge){s.Prestige.resets=1;s.Lifetime.hardwareClasses=new[]{ChallengeRules.Definition("no-taps",1).EntryHardware};s=ChallengeRules.Start(s,"no-taps",1,"blueprint-reward-proof");Assert.That(ChallengeRules.Active(s),Is.True);s.Research[Array.FindIndex(Balance.Research,r=>r.Id=="blueprints")]=1;}long before=s.Workshop.fragments;Workshop.ResearchComplete(s,"blueprints",new Job{paidDataRecorded=true,paidData=ScientificNumber.From(1000).ToData()});Assert.That(s.Workshop.blueprintReward,Is.EqualTo(!challenge));if(!challenge)Assert.That(s.Workshop.fragments-before,Is.EqualTo((long)ItemBalance.FirstBlueprintFragments));else Assert.That(s.Workshop.fragments,Is.EqualTo(before));}
   var capacity=Game.New(1000000);capacity.Workshop.fragments=9007199254740991L;capacity.Workshop.blueprintPending=true;Workshop.SettleBlueprintReward(capacity);Assert.That(capacity.Workshop.blueprintPending,Is.True);capacity.Workshop.fragments=0;Workshop.SettleBlueprintReward(capacity);Assert.That(capacity.Workshop.blueprintReward,Is.True);Assert.That(capacity.Journal.Has("blueprint-research-reward"),Is.True);long paid=capacity.Workshop.fragments;Workshop.SettleBlueprintReward(capacity);Assert.That(capacity.Workshop.fragments,Is.EqualTo(paid));}
 }
}
